-- Versioned staffed hours and immutable provider-template approval withdrawal.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.support_hours(singleton boolean primary key default true check(singleton),version integer not null default 1,weekly_intervals jsonb not null default '[]',response_target_minutes integer);
insert into app_private.support_hours(singleton)values(true);
create table app_private.support_hours_history(id uuid primary key default gen_random_uuid(),version integer not null unique,weekly_intervals jsonb not null,response_target_minutes integer,actor_account_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now());
create table app_private.whatsapp_template_revocations(template_id uuid primary key references app_private.whatsapp_templates(id),actor_account_id uuid not null references app_private.accounts(id),reason text not null,created_at timestamptz not null default now());
create function app_private.support_hours_snapshot(p_at timestamptz default now())returns jsonb language plpgsql stable security definer set search_path='' as $$declare config app_private.support_hours%rowtype;localtime timestamp:=p_at at time zone'Africa/Cairo';begin select * into config from app_private.support_hours where singleton;return jsonb_build_object('staffed_hours_configured',jsonb_array_length(config.weekly_intervals)>0,'staffed_hours',config.weekly_intervals,'staffed_hours_open',case when jsonb_array_length(config.weekly_intervals)>0 then exists(select 1 from jsonb_array_elements(config.weekly_intervals)i where(i->>'weekday')::integer=extract(isodow from localtime)::integer and localtime::time>=(i->>'start_local')::time and localtime::time<(i->>'end_local')::time)end,'staffed_target_minutes',config.response_target_minutes);end$$;
create or replace function app_private.support_summary(p_actor uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;c app_private.conversations%rowtype;begin result:=app_private.support_base_summary(p_actor,p_id);select * into c from app_private.conversations where id=p_id;return result||jsonb_build_object('can_handoff',coalesce(c.account_id=p_actor and c.state='bot',false),'can_link',coalesce(c.account_id=p_actor and not exists(select 1 from app_private.support_account_links where conversation_id=c.id),false),'can_escalate',coalesce(c.owner_account_id=p_actor and c.state='assigned'and app_private.support_staff(p_actor),false),'elapsed_wait_seconds',case when c.waiting_since is not null then greatest(0,floor(extract(epoch from now()-c.waiting_since)))::integer end,'can_return',c.state='escalated'and app_private.has_role(p_actor,'admin'),'consent_status',(select consent from app_private.whatsapp_channels where conversation_id=c.id))||app_private.support_hours_snapshot();end$$;
create function api.set_support_hours(p_weekly_intervals jsonb,p_response_target_minutes integer,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;v integer;begin perform app_private.require_role(actor,'admin');
 if jsonb_typeof(p_weekly_intervals)is distinct from'array'or jsonb_array_length(p_weekly_intervals)>28 or(p_response_target_minutes is not null and p_response_target_minutes not between 1 and 10080)then raise exception'VALIDATION_ERROR';end if;
 if exists(select 1 from jsonb_array_elements(p_weekly_intervals)i where jsonb_typeof(i)<>'object'or i-array['weekday','start_local','end_local']<>'{}'::jsonb or coalesce(i->>'weekday','')!~'^[1-7]$'or coalesce(i->>'start_local','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'or coalesce(i->>'end_local','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'or(i->>'start_local')>=(i->>'end_local'))then raise exception'VALIDATION_ERROR';end if;
 if exists(select 1 from jsonb_array_elements(p_weekly_intervals)with ordinality a(i,n)cross join jsonb_array_elements(p_weekly_intervals)with ordinality b(i,n)where a.n<b.n and a.i->>'weekday'=b.i->>'weekday'and a.i->>'start_local'<b.i->>'end_local'and b.i->>'start_local'<a.i->>'end_local')then raise exception'VALIDATION_ERROR';end if;
 select version into v from app_private.support_hours where singleton for update;ctx:=app_private.booking_begin(actor,'set_support_hours',jsonb_build_object('weekly_intervals',p_weekly_intervals,'response_target_minutes',p_response_target_minutes,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;if v<>p_expected_version then raise exception'VERSION_CONFLICT';end if;
 v:=v+1;update app_private.support_hours set version=v,weekly_intervals=p_weekly_intervals,response_target_minutes=p_response_target_minutes where singleton;insert into app_private.support_hours_history(version,weekly_intervals,response_target_minutes,actor_account_id)values(v,p_weekly_intervals,p_response_target_minutes,actor);return app_private.booking_finish(ctx,actor,v,jsonb_build_object('settings_version',v),'support_hours_changed',jsonb_build_object('version',v));end$$;
create function api.revoke_whatsapp_template(p_template_id uuid,p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;begin perform app_private.require_role(actor,'admin');if length(btrim(p_reason))not between 1 and 2000 or p_reason is null then raise exception'VALIDATION_ERROR';end if;perform 1 from app_private.whatsapp_templates where id=p_template_id for update;if not found then raise exception'NOT_FOUND';end if;
 ctx:=app_private.booking_begin(actor,'revoke_whatsapp_template',jsonb_build_object('template_id',p_template_id,'reason',p_reason),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 insert into app_private.whatsapp_template_revocations values(p_template_id,actor,p_reason,now())on conflict do nothing;return app_private.booking_finish(ctx,p_template_id,1,jsonb_build_object('template_id',p_template_id),'whatsapp_template_revoked',jsonb_build_object('template_id',p_template_id));end$$;
create or replace function api.get_support_options()returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();begin if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;return jsonb_build_object('is_admin',app_private.has_role(actor,'admin'),'staff',(select coalesce(jsonb_agg(jsonb_build_object('account_id',a.id,'label',p.display_name)order by p.display_name),'[]')from app_private.accounts a join app_private.people p on p.id=a.person_id where app_private.support_staff(a.id)),'templates',(select coalesce(jsonb_agg(jsonb_build_object('template_id',t.id,'name',t.name,'language',t.language,'parameter_count',t.parameter_count,'provider_mode',t.provider_mode)order by t.created_at desc),'[]')from app_private.whatsapp_templates t where t.approved and not exists(select 1 from app_private.whatsapp_template_revocations r where r.template_id=t.id)),'hours',(select jsonb_build_object('version',version,'weekly_intervals',weekly_intervals,'response_target_minutes',response_target_minutes)from app_private.support_hours where singleton));end$$;
-- System acknowledgements reflect configured hours without exposing internal records.
create or replace function app_private.support_add_message(p_conversation uuid,p_actor uuid,p_author text,p_text text,p_client uuid default null,p_delivery text default'delivered')returns uuid language plpgsql security definer set search_path='' as $$declare id uuid:=gen_random_uuid();body text:=p_text;begin
 if p_author='system'and exists(select 1 from app_private.support_hours where singleton and jsonb_array_length(weekly_intervals)>0)then body:=replace(replace(body,'The team will respond when available; staffed hours have not yet been configured.','The team will respond during the staffed hours shown in Support. Your place in the queue is preserved.'),'Staffed hours are not yet configured; the team will respond when available.','The team will respond during the staffed hours shown on the Git Tutor support page. Your place in the queue is preserved.');end if;
 insert into app_private.support_messages(id,conversation_id,actor_account_id,author,text,client_message_id)values(id,p_conversation,p_actor,p_author,body,p_client);insert into app_private.support_message_delivery(message_id,state)values(id,p_delivery);return id;end$$;
do $$declare t record;f record;begin
 for t in select tablename from pg_tables where schemaname='app_private'and tablename in('support_hours','support_hours_history','whatsapp_template_revocations')loop execute format('alter table app_private.%I enable row level security',t.tablename);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t.tablename);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t.tablename);execute format('grant select,insert on app_private.%I to git_tutor_commands',t.tablename);if t.tablename='support_hours'then execute format('grant update on app_private.%I to git_tutor_commands',t.tablename);else execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t.tablename);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname=any(array['support_hours_snapshot','set_support_hours','revoke_whatsapp_template'])loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;

create or replace function app_private.support_command(p_name text,p_input jsonb,p_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);c app_private.conversations%rowtype;channel app_private.whatsapp_channels%rowtype;t app_private.whatsapp_templates%rowtype;ctx jsonb;mid uuid;result jsonb;begin
 if p_name in('submit_message','request_handoff')and not app_private.support_read_scope(actor,(p_input->>'conversation_id')::uuid)then raise exception'FORBIDDEN';end if;
 if p_name<>'reply_to_conversation'or not exists(select 1 from app_private.conversations candidate where candidate.id=(p_input->>'conversation_id')::uuid and candidate.channel='whatsapp')then result:=app_private.support_website_command(p_name,p_input,p_key);if p_name in('transfer_conversation','escalate_conversation')then perform app_private.enqueue_event(md5('support:'||(result->>'command_id'))::uuid,case when p_name='transfer_conversation'then'support_transferred'else'support_escalated'end,(result->>'conversation_id')::uuid,jsonb_build_object('conversation_id',result->>'conversation_id','version',result->'version'),'notifications.route');end if;return result;end if;
 perform app_private.require_actor();select * into c from app_private.conversations where id=(p_input->>'conversation_id')::uuid for update;if not app_private.support_staff(actor)or c.owner_account_id is distinct from actor then raise exception'OWNER_REQUIRED';end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if c.version is distinct from(p_input->>'expected_version')::integer then raise exception'VERSION_CONFLICT';end if;if c.state<>'assigned'then raise exception'STATE_CONFLICT';end if;
 select * into channel from app_private.whatsapp_channels where conversation_id=c.id for update;if channel.consent='opted_out'then raise exception'CONSENT_REQUIRED';end if;
 if(p_input->>'text'is null)=(p_input->>'template_id'is null)then raise exception'VALIDATION_ERROR';end if;
 if p_input->>'template_id'is null then
  if c.last_whatsapp_user_message_at is null or c.last_whatsapp_user_message_at<=now()-interval'24 hours'then raise exception'WINDOW_CLOSED';end if;
  if length(btrim(p_input->>'text'))not between 1 and 4000 or p_input->'template_parameters'<>'[]'::jsonb then raise exception'VALIDATION_ERROR';end if;
 else
  select * into t from app_private.whatsapp_templates where id=(p_input->>'template_id')::uuid;
  if t.id is null or not t.approved or t.provider_mode<>channel.provider_mode or exists(select 1 from app_private.whatsapp_template_revocations r where r.template_id=t.id)then raise exception'TEMPLATE_REQUIRED';end if;
  if channel.consent<>'opted_in'then raise exception'CONSENT_REQUIRED';end if;
  if jsonb_typeof(p_input->'template_parameters')is distinct from'array'or jsonb_array_length(p_input->'template_parameters')<>t.parameter_count or exists(select 1 from jsonb_array_elements(p_input->'template_parameters')v where jsonb_typeof(v)<>'string'or length(v#>>'{}')not between 1 and 500)then raise exception'VALIDATION_ERROR';end if;
 end if;
 mid:=app_private.support_queue_whatsapp(c.id,actor,'staff',coalesce(btrim(p_input->>'text'),'Approved template: '||t.name),(p_input->>'template_id')::uuid,p_input->'template_parameters');update app_private.conversations set version=version+1,waiting_since=null,updated_at=now()where id=c.id returning * into c;
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',c.owner_account_id),'support_reply_queued',jsonb_build_object('conversation_id',c.id,'message_id',mid));end$$;
drop function app_private.prepare_whatsapp_send(uuid,uuid,uuid,text);
create function app_private.prepare_whatsapp_send(p_message uuid,p_job uuid,p_lease uuid,p_mode text,p_phone text default null)returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.conversations%rowtype;w app_private.whatsapp_channels%rowtype;m app_private.support_messages%rowtype;d app_private.support_message_delivery%rowtype;q app_private.whatsapp_dispatch%rowtype;t app_private.whatsapp_templates%rowtype;code text;begin
 perform app_private.whatsapp_assert_job(p_message,p_job,p_lease);select * into m from app_private.support_messages where id=p_message;select * into c from app_private.conversations where id=m.conversation_id for update;select * into w from app_private.whatsapp_channels where conversation_id=c.id for update;select * into d from app_private.support_message_delivery where message_id=m.id for update;select * into q from app_private.whatsapp_dispatch where message_id=m.id;
 if q.message_id is null or p_mode not in('fake','cloud')then raise exception'NOT_FOUND';end if;if q.template_id is not null then select * into t from app_private.whatsapp_templates where id=q.template_id for share;end if;
 if d.state in('sent','delivered','read','failed','suppressed')then return jsonb_build_object('state','complete','message_id',m.id);end if;
 if w.provider_mode<>p_mode or(p_mode='cloud'and w.phone_number_id is distinct from p_phone)then code:='PROVIDER_MODE_MISMATCH';elsif w.consent='opted_out'then code:='CONSENT_REQUIRED';elsif c.ownership_version<>q.ownership_version or(m.author='bot'and(c.bot_paused or c.state<>'bot'))or(m.author='staff'and(c.owner_account_id is distinct from m.actor_account_id or c.state<>'assigned'or not app_private.support_staff(m.actor_account_id)))then code:='CURRENT_OWNER_REQUIRED';
 elsif q.template_id is null and(c.last_whatsapp_user_message_at is null or c.last_whatsapp_user_message_at<=clock_timestamp()-interval'24 hours')then code:='WINDOW_CLOSED';
 elsif q.template_id is not null then select * into t from app_private.whatsapp_templates where id=q.template_id for share;if t.id is null or not t.approved or t.provider_mode<>p_mode or exists(select 1 from app_private.whatsapp_template_revocations r where r.template_id=t.id)then code:='TEMPLATE_REQUIRED';elsif w.consent<>'opted_in'then code:='CONSENT_REQUIRED';end if;end if;
 if code is not null and d.state<>'unknown'then update app_private.support_message_delivery set state='suppressed',safe_error_code=code,updated_at=now()where message_id=m.id;return jsonb_build_object('state','complete','message_id',m.id);end if;
 return jsonb_build_object('state','ready','message_id',m.id,'attempt_state',d.state,'destination',w.wa_id,'text',case when q.template_id is null then m.text end,'template',case when q.template_id is not null then jsonb_build_object('name',t.name,'language',t.language,'parameters',q.template_parameters)end,'scenario',case when p_mode='fake'then q.scenario else'success'end);end$$;

alter function app_private.prepare_whatsapp_send(uuid,uuid,uuid,text,text) owner to git_tutor_commands;
revoke all on function app_private.prepare_whatsapp_send(uuid,uuid,uuid,text,text) from public,anon,authenticated,service_role;
grant execute on function app_private.prepare_whatsapp_send(uuid,uuid,uuid,text,text) to git_tutor_worker;

create or replace function api.get_conversation(p_conversation_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);result jsonb;messages jsonb;notes jsonb;begin
 if not exists(select 1 from app_private.conversations where id=p_conversation_id and(account_id=actor or owner_account_id=actor or app_private.has_role(actor,'admin')or(state='waiting'and owner_account_id is null and app_private.support_staff(actor))))then raise exception'FORBIDDEN';end if;result:=app_private.support_summary(actor,p_conversation_id);select coalesce(jsonb_agg(x.item order by x.sequence),'[]'::jsonb)into messages from(select m.sequence,jsonb_build_object('message_id',m.id,'author',m.author,'text',m.text,'created_at',m.created_at,'delivery_state',d.state)||case when app_private.support_staff(actor)then jsonb_build_object('can_reconcile',d.state='unknown'or(d.state='queued'and exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where e.aggregate_id=m.id and j.purpose='support.whatsapp_send'and(j.state='reconciliation'or(j.state='leased'and j.lease_expires_at<=clock_timestamp())))),'delivery_error_code',d.safe_error_code)else'{}'::jsonb end item from app_private.support_messages m join app_private.support_message_delivery d on d.message_id=m.id where m.conversation_id=p_conversation_id order by m.sequence desc limit 100)x;
 result:=result||jsonb_build_object('messages',messages,'earlier_messages_available',(select count(*)>100 from app_private.support_messages where conversation_id=p_conversation_id));
 if app_private.has_role(actor,'admin')or exists(select 1 from app_private.conversations where id=p_conversation_id and owner_account_id=actor)then select coalesce(jsonb_agg(jsonb_build_object('note_id',n.id,'text',n.text,'created_at',n.created_at)order by n.created_at,n.id),'[]'::jsonb)into notes from app_private.support_notes n where n.conversation_id=p_conversation_id;result:=result||jsonb_build_object('private_notes',notes);end if;return result;end$$;

create or replace function app_private.whatsapp_observe(p_message uuid,p_source text,p_outcome text,p_provider_id text,p_code text)returns jsonb language plpgsql security definer set search_path='' as $$declare d app_private.support_message_delivery%rowtype;nextstate text;begin
 if p_outcome not in('sent','delivered','read','failed','unknown')or(p_code is not null and p_code!~'^[A-Z0-9_]{1,80}$')then raise exception'VALIDATION_ERROR';end if;
 select * into d from app_private.support_message_delivery where message_id=p_message for update;if d.message_id is null then raise exception'NOT_FOUND';end if;
 if d.provider_message_id is not null and p_provider_id is not null and d.provider_message_id<>p_provider_id then raise exception'STATE_CONFLICT';end if;
 if exists(select 1 from app_private.whatsapp_observations where source_identity=p_source)then return jsonb_build_object('state',d.state);end if;
 insert into app_private.whatsapp_observations(message_id,source_identity,outcome,provider_message_id,safe_error_code)values(p_message,p_source,p_outcome,p_provider_id,p_code);
 nextstate:=case when d.state='read'or p_outcome='read'then'read'when d.state='delivered'or p_outcome='delivered'then'delivered'when d.state='suppressed'then'suppressed'when d.state='failed'or p_outcome='failed'then'failed'when d.state='sent'or p_outcome='sent'then'sent'else p_outcome end;
 update app_private.support_message_delivery set state=nextstate,provider_message_id=coalesce(provider_message_id,p_provider_id),safe_error_code=case when nextstate in('failed','unknown')then p_code end,updated_at=now()where message_id=p_message;return jsonb_build_object('state',nextstate);end$$;

revoke create on schema api,app_private from git_tutor_commands;
